mapper.select:
select * from ai_message
where conversation_id = #{conversationId}
order by id asc

select * from ai_message
where id = #{id}
limit 1

select a.conversation_id, u.id as user_message_id, a.id as assistant_message_id, u.content as user_question, a.content as assistant_reply, a.tool_name as route, a.action_type, case when a.action_type = 'cancel_order' then '涉及取消订单动作' when a.action_type = 'remind_order' then '涉及催单动作' when a.action_type = 'after_sale' then '涉及售后申请动作' when a.tool_name = 'action' then '命中高风险业务动作路由' when a.content like '%确认%' then '涉及用户确认的高风险业务动作' when a.content like '%取消订单%' then '涉及取消订单动作' when a.content like '%售后申请%' then '涉及售后申请动作' when a.content like '%催单%' then '涉及催单动作' else '命中高风险关键词' end as risk_reason, a.audit_status, a.audit_remark, a.approval_status, a.approval_remark, a.approval_user_id, a.approval_time, a.create_time from ai_message a left join ai_message u on u.id = ( select max(prev_msg.id) from ai_message prev_msg where prev_msg.conversation_id = a.conversation_id and prev_msg.id < a.id and prev_msg.role = 'user' ) where a.role = 'assistant' and ( a.action_type is not null or a.tool_name = 'action' or a.content like '%确认%' or a.content like '%取消订单%' or a.content like '%售后申请%' or a.content like '%催单%' )
and a.conversation_id = #{conversationId}
and a.user_id = #{userId}
and a.action_type = #{actionType}
and a.audit_status = #{auditStatus}
and a.approval_status = #{approvalStatus}
and a.approval_user_id = #{approvalUserId}
and ( u.content like concat('%', #{questionKeyword}, '%') or a.content like concat('%', #{questionKeyword}, '%') )
and a.create_time >= #{beginTime}
and a.create_time <= #{endTime}
and a.approval_time >= #{approvalBeginTime}
and a.approval_time <= #{approvalEndTime}
order by a.id desc

select
    count(1) as total_count,
    sum(case when ifnull(a.audit_status, 0) = 0 then 1 else 0 end) as pending_count,
    sum(case when a.audit_status = 1 then 1 else 0 end) as confirmed_count,
    sum(case when a.audit_status = 2 then 1 else 0 end) as ignored_count,
    sum(case when ifnull(a.approval_status, 0) = 0 then 1 else 0 end) as approval_pending_count,
    sum(case when a.approval_status = 1 then 1 else 0 end) as approval_approved_count,
    sum(case when a.approval_status = 2 then 1 else 0 end) as approval_rejected_count
from ai_message a
         left join ai_message u on u.id = (
    select max(prev_msg.id)
    from ai_message prev_msg
    where prev_msg.conversation_id = a.conversation_id
      and prev_msg.id < a.id
      and prev_msg.role = 'user'
)
where a.role = 'assistant'
  and (
    a.action_type is not null
        or a.tool_name = 'action'
        or a.content like '%确认%'
        or a.content like '%取消订单%'
        or a.content like '%售后申请%'
        or a.content like '%催单%'
    )

    and a.conversation_id = #{conversationId}


    and a.user_id = #{userId}


    and a.action_type = #{actionType}


    and a.audit_status = #{auditStatus}


    and a.approval_status = #{approvalStatus}


    and a.approval_user_id = #{approvalUserId}


    and (
        u.content like concat('%', #{questionKeyword}, '%')
        or a.content like concat('%', #{questionKeyword}, '%')
    )


    and a.create_time  >=  #{beginTime}


    and a.create_time  <=  #{endTime}


    and a.approval_time  >=  #{approvalBeginTime}


    and a.approval_time  <=  #{approvalEndTime}

select
    sum(case when a.approval_status in (1, 2) then 1 else 0 end) as approval_total_count,
    sum(case when a.approval_status = 1 then 1 else 0 end) as approval_approved_count,
    sum(case when a.approval_status = 2 then 1 else 0 end) as approval_rejected_count
from ai_message a
         left join ai_message u on u.id = (
    select max(prev_msg.id)
    from ai_message prev_msg
    where prev_msg.conversation_id = a.conversation_id
      and prev_msg.id < a.id
      and prev_msg.role = 'user'
)
where a.role = 'assistant'
  and (
    a.action_type is not null
        or a.tool_name = 'action'
        or a.content like '%确认%'
        or a.content like '%取消订单%'
        or a.content like '%售后申请%'
        or a.content like '%催单%'
    )

    and a.conversation_id = #{conversationId}


    and a.user_id = #{userId}


    and a.approval_user_id = #{approvalUserId}


    and a.action_type = #{actionType}


    and a.audit_status = #{auditStatus}


    and a.approval_status = #{approvalStatus}


    and (
        u.content like concat('%', #{questionKeyword}, '%')
        or a.content like concat('%', #{questionKeyword}, '%')
    )


    and a.create_time  >=  #{beginTime}


    and a.create_time  <=  #{endTime}


    and a.approval_time  >=  #{approvalBeginTime}


    and a.approval_time  <=  #{approvalEndTime}

select
    date_format(a.create_time, '%Y-%m-%d') as stat_date,
    count(1) as risk_hit_count,
    sum(case when a.approval_status = 1 then 1 else 0 end) as approval_approved_count,
    sum(case when a.approval_status = 2 then 1 else 0 end) as approval_rejected_count,
    case
        when sum(case when a.approval_status in (1, 2) then 1 else 0 end) = 0 then 0
        else round(
            sum(case when a.approval_status = 1 then 1 else 0 end) * 100.0 /
            sum(case when a.approval_status in (1, 2) then 1 else 0 end), 2
        )
        end as approval_pass_rate
from ai_message a
         left join ai_message u on u.id = (
    select max(prev_msg.id)
    from ai_message prev_msg
    where prev_msg.conversation_id = a.conversation_id
      and prev_msg.id < a.id
      and prev_msg.role = 'user'
)
where a.role = 'assistant'
  and (
    a.action_type is not null
        or a.tool_name = 'action'
        or a.content like '%确认%'
        or a.content like '%取消订单%'
        or a.content like '%售后申请%'
        or a.content like '%催单%'
    )

    and a.conversation_id = #{conversationId}


    and a.user_id = #{userId}


    and a.approval_user_id = #{approvalUserId}


    and a.action_type = #{actionType}


    and a.audit_status = #{auditStatus}


    and a.approval_status = #{approvalStatus}


    and (
        u.content like concat('%', #{questionKeyword}, '%')
        or a.content like concat('%', #{questionKeyword}, '%')
    )


    and a.create_time  >=  #{beginTime}


    and a.create_time  <=  #{endTime}


    and a.approval_time  >=  #{approvalBeginTime}


    and a.approval_time  <=  #{approvalEndTime}

group by date_format(a.create_time, '%Y-%m-%d')
order by stat_date asc

select
    date_format(a.create_time, '%Y-%m-%d') as stat_date,
    sum(case when a.action_type = 'cancel_order' then 1 else 0 end) as cancel_order_count,
    sum(case when a.action_type = 'remind_order' then 1 else 0 end) as remind_order_count,
    sum(case when a.action_type = 'after_sale' then 1 else 0 end) as after_sale_count
from ai_message a
         left join ai_message u on u.id = (
    select max(prev_msg.id)
    from ai_message prev_msg
    where prev_msg.conversation_id = a.conversation_id
      and prev_msg.id < a.id
      and prev_msg.role = 'user'
)
where a.role = 'assistant'
  and a.action_type is not null

    and a.conversation_id = #{conversationId}


    and a.user_id = #{userId}


    and a.approval_user_id = #{approvalUserId}


    and a.action_type = #{actionType}


    and a.approval_status = #{approvalStatus}


    and (
        u.content like concat('%', #{questionKeyword}, '%')
        or a.content like concat('%', #{questionKeyword}, '%')
    )


    and a.create_time  >=  #{beginTime}


    and a.create_time  <=  #{endTime}

group by date_format(a.create_time, '%Y-%m-%d')
order by stat_date asc

select
    a.action_type,
    sum(case when a.approval_status in (1, 2) then 1 else 0 end) as approval_total_count,
    sum(case when a.approval_status = 1 then 1 else 0 end) as approval_approved_count,
    case
        when sum(case when a.approval_status in (1, 2) then 1 else 0 end) = 0 then 0
        else round(
            sum(case when a.approval_status = 1 then 1 else 0 end) * 100.0 /
            sum(case when a.approval_status in (1, 2) then 1 else 0 end), 2
        )
        end as approval_pass_rate
from ai_message a
         left join ai_message u on u.id = (
    select max(prev_msg.id)
    from ai_message prev_msg
    where prev_msg.conversation_id = a.conversation_id
      and prev_msg.id < a.id
      and prev_msg.role = 'user'
)
where a.role = 'assistant'
  and a.action_type is not null

    and a.conversation_id = #{conversationId}


    and a.user_id = #{userId}


    and a.approval_user_id = #{approvalUserId}


    and a.action_type = #{actionType}


    and a.approval_status = #{approvalStatus}


    and (
        u.content like concat('%', #{questionKeyword}, '%')
        or a.content like concat('%', #{questionKeyword}, '%')
    )


    and a.create_time  >=  #{beginTime}


    and a.create_time  <=  #{endTime}


    and a.approval_time  >=  #{approvalBeginTime}


    and a.approval_time  <=  #{approvalEndTime}

group by a.action_type
order by approval_pass_rate desc, approval_total_count desc
